(function(){
"use strict";
var Widget = require("$:/core/modules/widgets/widget.js").widget;
function pad(n){ return (n<10?"0":"")+n; }

/* ---- live clock ---- */
var Clock = function(node,opts){ this.initialise(node,opts); };
Clock.prototype = new Widget();
Clock.prototype.render = function(parent,nextSibling){
	this.parentDomNode = parent;
	this.computeAttributes();
	this.execute();
	var self = this;
	var span = this.document.createElement("span");
	span.className = "momentum-time";
	parent.insertBefore(span,nextSibling);
	this.domNodes.push(span);
	this.clockNode = span;
	this.tick();
	if($tw.browser && typeof setInterval !== "undefined"){
		this.timer = setInterval(function(){
			if(self.clockNode && self.clockNode.isConnected === false){ clearInterval(self.timer); self.timer = null; return; }
			self.tick();
		},1000);
	}
};
Clock.prototype.execute = function(){
	this.is24 = (this.getAttribute("format","24") !== "12");
	this.showSeconds = (this.getAttribute("seconds","no") === "yes");
};
Clock.prototype.tick = function(){
	var d = new Date(), h = d.getHours(), m = d.getMinutes(), s = d.getSeconds(), suffix = "";
	if(!this.is24){ suffix = (h < 12) ? " AM" : " PM"; h = h % 12; if(h === 0){ h = 12; } }
	var out = h + ":" + pad(m) + (this.showSeconds ? (":" + pad(s)) : "") + suffix;
	if(this.clockNode){ this.clockNode.textContent = out; }
};
Clock.prototype.refresh = function(changedTiddlers){
	var changed = this.computeAttributes();
	if(changed.format || changed.seconds){
		if(this.timer){ clearInterval(this.timer); this.timer = null; }
		this.refreshSelf();
		return true;
	}
	return false;
};
Clock.prototype.destroy = function(){
	if(this.timer){ clearInterval(this.timer); this.timer = null; }
	if(Widget.prototype.destroy){ Widget.prototype.destroy.call(this); }
};
exports.momentumclock = Clock;

/* ---- greeting ---- */
var Greeting = function(node,opts){ this.initialise(node,opts); };
Greeting.prototype = new Widget();
Greeting.prototype.render = function(parent,nextSibling){
	this.parentDomNode = parent;
	this.computeAttributes();
	this.execute();
	var self = this;
	var span = this.document.createElement("span");
	span.className = "momentum-greeting-word";
	parent.insertBefore(span,nextSibling);
	this.domNodes.push(span);
	this.node = span;
	this.update();
	if($tw.browser && typeof setInterval !== "undefined"){
		this.timer = setInterval(function(){
			if(self.node && self.node.isConnected === false){ clearInterval(self.timer); self.timer = null; return; }
			self.update();
		},30000);
	}
};
Greeting.prototype.execute = function(){
	this.morning = this.getAttribute("morning","Good morning");
	this.afternoon = this.getAttribute("afternoon","Good afternoon");
	this.evening = this.getAttribute("evening","Good evening");
	this.night = this.getAttribute("night","Good evening");
};
Greeting.prototype.update = function(){
	var h = new Date().getHours(), t;
	if(h < 5){ t = this.night; } else if(h < 12){ t = this.morning; } else if(h < 18){ t = this.afternoon; } else { t = this.evening; }
	if(this.node){ this.node.textContent = t; }
};
Greeting.prototype.refresh = function(changedTiddlers){
	var changed = this.computeAttributes();
	if(Object.keys(changed).length){
		if(this.timer){ clearInterval(this.timer); this.timer = null; }
		this.refreshSelf();
		return true;
	}
	return false;
};
Greeting.prototype.destroy = function(){
	if(this.timer){ clearInterval(this.timer); this.timer = null; }
	if(Widget.prototype.destroy){ Widget.prototype.destroy.call(this); }
};
exports.momentumgreeting = Greeting;

/* ---- daily quote ---- */
var Quote = function(node,opts){ this.initialise(node,opts); };
Quote.prototype = new Widget();
Quote.prototype.render = function(parent,nextSibling){
	this.parentDomNode = parent;
	this.computeAttributes();
	this.execute();
	var list = this.getQuotes();
	var wrap = this.document.createElement("span");
	wrap.className = "momentum-quote-wrap";
	if(list.length){
		var idx = Math.floor(Date.now() / 86400000) % list.length;
		var q = list[idx] || {};
		var qs = this.document.createElement("span");
		qs.className = "momentum-quote-text";
		qs.textContent = "\u201C" + (q.text || "") + "\u201D";
		wrap.appendChild(qs);
		if(q.author){
			var as = this.document.createElement("span");
			as.className = "momentum-quote-author";
			as.textContent = "\u2014 " + q.author;
			wrap.appendChild(as);
		}
	}
	parent.insertBefore(wrap,nextSibling);
	this.domNodes.push(wrap);
};
Quote.prototype.execute = function(){
	this.source = this.getAttribute("tiddler","$:/plugins/claude/momentum/quotes");
};
Quote.prototype.getQuotes = function(){
	var text = this.wiki.getTiddlerText(this.source,"");
	if(!text){ return []; }
	try {
		var d = JSON.parse(text);
		if($tw.utils.isArray(d)){ return d; }
		return d.quotes || [];
	} catch(e){ return []; }
};
Quote.prototype.refresh = function(){ return false; };
exports.momentumquote = Quote;

/* ---- daily photo fetch (Unsplash) ---- */
var Photo = function(node,opts){ this.initialise(node,opts); };
Photo.prototype = new Widget();
Photo.prototype.render = function(parent,nextSibling){
	this.parentDomNode = parent;
	this.computeAttributes();
	this.execute();
	var span = this.document.createElement("span");
	span.style.display = "none";
	parent.insertBefore(span,nextSibling);
	this.domNodes.push(span);
	if($tw.browser){ this.fetchIfNeeded(); this.setupRefreshTimer(); }
};
Photo.prototype.execute = function(){
	this.cacheTitle = this.getAttribute("cache","$:/temp/momentum/dailyphoto");
	this.unsplashKeyTitle = this.getAttribute("key","$:/config/momentum/unsplashkey");
	this.pexelsKeyTitle = "$:/config/momentum/pexelskey";
	this.sourceTitle = "$:/config/momentum/photosource";
	this.collectionTitle = "$:/config/momentum/unsplashcollection";
	this.bgTitle = this.getAttribute("background","$:/config/momentum/background");
	this.refreshIntervalTitle = "$:/config/momentum/photorefreshinterval";
};
Photo.prototype.todayStamp = function(){
	var d = new Date(), mm = d.getMonth()+1, dd = d.getDate();
	return "" + d.getFullYear() + (mm<10?"0":"")+mm + (dd<10?"0":"")+dd;
};
Photo.prototype.fetchIfNeeded = function(){
	var custom = (this.wiki.getTiddlerText(this.bgTitle,"") || "").trim();
	if(custom){ return; }
	var source = (this.wiki.getTiddlerText(this.sourceTitle,"unsplash") || "unsplash").trim();
	if(source === "picsum"){ return; }
	var today = this.todayStamp();
	var cache = this.wiki.getTiddler(this.cacheTitle);
	if(cache && cache.fields.date === today){ return; }
	if(this.fetchInFlight === today){ return; }
	if(typeof fetch !== "function"){ return; }
	if(source === "pexels"){
		var pkey = (this.wiki.getTiddlerText(this.pexelsKeyTitle,"") || "").trim();
		if(!pkey){ return; }
		this.fetchInFlight = today;
		this.fetchPexels(pkey,today);
		return;
	}
	var key = (this.wiki.getTiddlerText(this.unsplashKeyTitle,"") || "").trim();
	if(!key){ return; }
	this.fetchInFlight = today;
	this.fetchUnsplash(key,today);
};
Photo.prototype.fetchUnsplash = function(key,today){
	var self = this;
	var collection = (this.wiki.getTiddlerText(this.collectionTitle,"") || "").trim();
	var url = "https://api.unsplash.com/photos/random?orientation=landscape&content_filter=high";
	if(collection){ url += "&collections=" + encodeURIComponent(collection); }
	fetch(url,{headers:{Authorization:"Client-ID " + key}}).then(function(r){
		return r.json();
	}).then(function(data){
		var loc = "";
		if(data && data.location){
			loc = data.location.name || [data.location.city,data.location.country].filter(Boolean).join(", ");
		}
		var u = (data && data.urls && (data.urls.full || data.urls.regular)) || "";
		self.fetchInFlight = null;
		self.wiki.addTiddler(new $tw.Tiddler({title:self.cacheTitle,date:today,url:u,location:loc}));
	}).catch(function(){
		self.fetchInFlight = null;
		self.wiki.addTiddler(new $tw.Tiddler({title:self.cacheTitle,date:today,url:"",location:""}));
	});
};
Photo.prototype.fetchPexels = function(key,today){
	var self = this;
	var page = 1 + Math.floor(Math.random() * 200);
	fetch("https://api.pexels.com/v1/curated?per_page=1&page=" + page,{headers:{Authorization:key}}).then(function(r){
		return r.json();
	}).then(function(data){
		var photo = data && data.photos && data.photos[0];
		var u = (photo && photo.src && (photo.src.large2x || photo.src.large)) || "";
		var loc = photo && photo.photographer ? ("Photo by " + photo.photographer) : "";
		self.fetchInFlight = null;
		self.wiki.addTiddler(new $tw.Tiddler({title:self.cacheTitle,date:today,url:u,location:loc}));
	}).catch(function(){
		self.fetchInFlight = null;
		self.wiki.addTiddler(new $tw.Tiddler({title:self.cacheTitle,date:today,url:"",location:""}));
	});
};
Photo.prototype.refresh = function(changedTiddlers){
	this.computeAttributes();
	if(changedTiddlers[this.cacheTitle] || changedTiddlers[this.bgTitle] || changedTiddlers[this.unsplashKeyTitle] ||
		changedTiddlers[this.pexelsKeyTitle] || changedTiddlers[this.sourceTitle] || changedTiddlers[this.collectionTitle]){
		this.fetchIfNeeded();
	}
	if(changedTiddlers[this.refreshIntervalTitle]){
		this.setupRefreshTimer();
	}
	return false;
};
Photo.prototype.setupRefreshTimer = function(){
	if(this.refreshTimer){ clearInterval(this.refreshTimer); this.refreshTimer = null; }
	var intervalStr = (this.wiki.getTiddlerText(this.refreshIntervalTitle,"0") || "0").trim();
	var intervalMinutes = parseInt(intervalStr, 10);
	if(intervalMinutes > 0){
		var self = this;
		var intervalMs = intervalMinutes * 60 * 1000;
		this.refreshTimer = setInterval(function(){
			self.forceRefresh();
		}, intervalMs);
	}
};
Photo.prototype.forceRefresh = function(){
	this.wiki.deleteTiddler(this.cacheTitle);
	this.fetchIfNeeded();
};
Photo.prototype.destroy = function(){
	if(this.refreshTimer){ clearInterval(this.refreshTimer); this.refreshTimer = null; }
	if(Widget.prototype.destroy){ Widget.prototype.destroy.call(this); }
};
exports.momentumphoto = Photo;

/* ---- weather ---- */
var Weather = function(node,opts){ this.initialise(node,opts); };
Weather.prototype = new Widget();
Weather.prototype.CODES = {
	0: "\u2600\ufe0f", 1: "\ud83c\udf24\ufe0f", 2: "\u26c5", 3: "\u2601\ufe0f",
	45: "\ud83c\udf2b\ufe0f", 48: "\ud83c\udf2b\ufe0f",
	51: "\ud83c\udf26\ufe0f", 53: "\ud83c\udf26\ufe0f", 55: "\ud83c\udf26\ufe0f",
	56: "\ud83c\udf27\ufe0f", 57: "\ud83c\udf27\ufe0f",
	61: "\ud83c\udf27\ufe0f", 63: "\ud83c\udf27\ufe0f", 65: "\ud83c\udf27\ufe0f",
	66: "\ud83c\udf27\ufe0f", 67: "\ud83c\udf27\ufe0f",
	71: "\ud83c\udf28\ufe0f", 73: "\ud83c\udf28\ufe0f", 75: "\ud83c\udf28\ufe0f", 77: "\ud83c\udf28\ufe0f",
	80: "\ud83c\udf26\ufe0f", 81: "\ud83c\udf27\ufe0f", 82: "\u26c8\ufe0f",
	85: "\ud83c\udf28\ufe0f", 86: "\ud83c\udf28\ufe0f",
	95: "\u26c8\ufe0f", 96: "\u26c8\ufe0f", 99: "\u26c8\ufe0f"
};
Weather.prototype.render = function(parent,nextSibling){
	this.parentDomNode = parent;
	this.computeAttributes();
	this.execute();
	var span = this.document.createElement("span");
	span.className = "momentum-weather";
	parent.insertBefore(span,nextSibling);
	this.domNodes.push(span);
	this.node = span;
	this.update();
	var self = this;
	if($tw.browser && typeof setInterval !== "undefined"){
		this.timer = setInterval(function(){
			if(self.node && self.node.isConnected === false){ clearInterval(self.timer); self.timer = null; return; }
			self.update();
		},60000);
	}
};
Weather.prototype.execute = function(){
	this.cacheTitle = this.getAttribute("cache","$:/temp/momentum/weather");
	this.locTitle = this.getAttribute("location","$:/config/momentum/weatherlocation");
	this.unitTitle = this.getAttribute("unit","$:/config/momentum/weatherunit");
};
Weather.prototype.update = function(){
	var cache = this.wiki.getTiddler(this.cacheTitle);
	var now = Date.now();
	if(cache && cache.fields.time && (now - Number(cache.fields.time)) < 1800000){
		this.paint(cache.fields);
	} else {
		this.fetchWeather();
	}
};
Weather.prototype.paint = function(fields){
	if(!this.node){ return; }
	if(!fields || fields.tempc === "" || fields.tempc === undefined){ this.node.textContent = ""; return; }
	var unit = (this.wiki.getTiddlerText(this.unitTitle,"c") || "c");
	var tempc = Number(fields.tempc);
	var temp = (unit === "f") ? Math.round(tempc * 9 / 5 + 32) : Math.round(tempc);
	var icon = this.CODES[Number(fields.code)] || "\ud83c\udf21\ufe0f";
	this.node.textContent = icon + " " + temp + "\u00b0" + (unit === "f" ? "F" : "C");
};
Weather.prototype.fetchWeather = function(){
	if(!$tw.browser || typeof fetch !== "function"){ return; }
	var self = this;
	var manual = (this.wiki.getTiddlerText(this.locTitle,"") || "").trim();
	if(manual){
		var parts = manual.split(",");
		var city = (parts[0] || "").trim();
		var countryHint = (parts[1] || "").trim().toLowerCase();
		var aliases = {"uk":"united kingdom","u.k.":"united kingdom","gb":"united kingdom","usa":"united states","u.s.":"united states","us":"united states","u.s.a.":"united states","uae":"united arab emirates"};
		if(aliases[countryHint]){ countryHint = aliases[countryHint]; }
		fetch("https://geocoding-api.open-meteo.com/v1/search?count=10&name=" + encodeURIComponent(city)).then(function(r){
			return r.json();
		}).then(function(g){
			var results = (g && g.results) || [];
			var hit = results[0];
			if(countryHint){
				for(var i=0;i<results.length;i++){
					var c = (results[i].country || "").toLowerCase();
					var cc = (results[i].country_code || "").toLowerCase();
					if(c.indexOf(countryHint) !== -1 || cc === countryHint){ hit = results[i]; break; }
				}
			}
			if(!hit){ self.markEmpty(); return; }
			self.fetchForecast(hit.latitude,hit.longitude);
		}).catch(function(){ self.markEmpty(); });
	} else if(navigator.geolocation){
		navigator.geolocation.getCurrentPosition(function(pos){
			self.fetchForecast(pos.coords.latitude,pos.coords.longitude);
		}, function(){ self.markEmpty(); }, {maximumAge:1800000,timeout:8000});
	} else {
		self.markEmpty();
	}
};
Weather.prototype.fetchForecast = function(lat,lon){
	var self = this;
	fetch("https://api.open-meteo.com/v1/forecast?latitude=" + lat + "&longitude=" + lon + "&current_weather=true").then(function(r){
		return r.json();
	}).then(function(data){
		var cw = data && data.current_weather;
		if(!cw){ self.markEmpty(); return; }
		self.wiki.addTiddler(new $tw.Tiddler({title:self.cacheTitle,time:String(Date.now()),tempc:String(cw.temperature),code:String(cw.weathercode)}));
		self.paint({tempc:cw.temperature,code:cw.weathercode});
	}).catch(function(){ self.markEmpty(); });
};
Weather.prototype.markEmpty = function(){
	this.wiki.addTiddler(new $tw.Tiddler({title:this.cacheTitle,time:String(Date.now()),tempc:"",code:""}));
	if(this.node){ this.node.textContent = ""; }
};
Weather.prototype.refresh = function(changedTiddlers){
	this.computeAttributes();
	if(changedTiddlers[this.locTitle]){
		this.wiki.deleteTiddler(this.cacheTitle);
		this.update();
		return false;
	}
	if(changedTiddlers[this.unitTitle]){
		var cache = this.wiki.getTiddler(this.cacheTitle);
		this.paint(cache ? cache.fields : null);
	}
	return false;
};
Weather.prototype.destroy = function(){
	if(this.timer){ clearInterval(this.timer); this.timer = null; }
	if(Widget.prototype.destroy){ Widget.prototype.destroy.call(this); }
};
exports.momentumweather = Weather;

/* ---- background contrast (auto light/dark text) ---- */
var Contrast = function(node,opts){ this.initialise(node,opts); };
Contrast.prototype = new Widget();
Contrast.prototype.render = function(parent,nextSibling){
	this.parentDomNode = parent;
	this.computeAttributes();
	this.execute();
	var span = this.document.createElement("span");
	span.style.display = "none";
	parent.insertBefore(span,nextSibling);
	this.domNodes.push(span);
	if($tw.browser){ this.analyseIfNeeded(); }
};
Contrast.prototype.execute = function(){
	this.src = this.getAttribute("src","");
	this.cacheTitle = this.getAttribute("cache","$:/temp/momentum/contrast");
};
Contrast.prototype.analyseIfNeeded = function(){
	if(!this.src){ return; }
	var cache = this.wiki.getTiddler(this.cacheTitle);
	if(cache && cache.fields.src === this.src){ return; }
	if(this.inFlight === this.src){ return; }
	this.inFlight = this.src;
	var self = this, src = this.src;
	var img = new Image();
	img.crossOrigin = "anonymous";
	img.onload = function(){
		self.inFlight = null;
		try {
			var c = self.document.createElement("canvas");
			c.width = 16; c.height = 16;
			var ctx = c.getContext("2d");
			ctx.drawImage(img,0,0,16,16);
			var data = ctx.getImageData(0,0,16,16).data;
			var total = 0, n = 0;
			for(var i = 0; i < data.length; i += 4){
				total += 0.299*data[i] + 0.587*data[i+1] + 0.114*data[i+2];
				n++;
			}
			var mode = (n && (total / n) > 150) ? "light" : "dark";
			self.wiki.addTiddler(new $tw.Tiddler({title:self.cacheTitle,src:src,mode:mode}));
		} catch(e){
			/* CORS-tainted canvas or decode failure: leave existing/default mode alone */
		}
	};
	img.onerror = function(){ self.inFlight = null; };
	img.src = src;
};
Contrast.prototype.refresh = function(changedTiddlers){
	var changed = this.computeAttributes();
	if(changed.src){
		this.execute();
		this.analyseIfNeeded();
	}
	return false;
};
exports.momentumcontrast = Contrast;

/* ---- keyboard shortcuts ---- */
var Shortcuts = function(node,opts){ this.initialise(node,opts); };
Shortcuts.prototype = new Widget();
Shortcuts.prototype.render = function(parent,nextSibling){
	this.parentDomNode = parent;
	this.computeAttributes();
	this.execute();
	var span = this.document.createElement("span");
	span.style.display = "none";
	parent.insertBefore(span,nextSibling);
	this.domNodes.push(span);
	if($tw.browser && typeof document !== "undefined"){
		var self = this;
		this.handler = function(ev){ self.handle(ev); };
		document.addEventListener("keydown",this.handler);
	}
};
Shortcuts.prototype.execute = function(){
	this.searchSelector = this.getAttribute("search",".momentum-search-input");
};
Shortcuts.prototype.handle = function(ev){
	// TiddlyWiki's edit-text widget re-dispatches every keydown onto the editor's
	// container so that keyboard widgets can see it. Those clones are plain Events
	// aimed at a <div>, so the "are we typing?" test below cannot tell that the
	// real target was an editor - ignore them and only act on genuine key events.
	if(typeof KeyboardEvent !== "undefined" && !(ev instanceof KeyboardEvent)){ return; }
	var t = ev.target, tag = t && t.tagName;
	var active = this.document.activeElement, activeTag = active && active.tagName;
	var isEditable = function(el,elTag){ return elTag === "INPUT" || elTag === "TEXTAREA" || !!(el && el.isContentEditable); };
	var typing = isEditable(t,tag) || isEditable(active,activeTag);
	if(ev.key === "/" && !typing){
		var box = document.querySelector(this.searchSelector);
		if(box){ ev.preventDefault(); box.focus(); }
	} else if(ev.key === "Escape" && typing && t.classList && t.classList.contains("momentum-search-input")){
		t.value = "";
		t.blur();
		this.wiki.setText("$:/temp/momentum/search",null,null,"");
	} else if(ev.key === "n" && !typing){
		ev.preventDefault();
		$tw.rootWidget.dispatchEvent({type:"tm-new-tiddler"});
	}
};
Shortcuts.prototype.refresh = function(){ return false; };
Shortcuts.prototype.destroy = function(){
	if(this.handler){ document.removeEventListener("keydown",this.handler); this.handler = null; }
	if(Widget.prototype.destroy){ Widget.prototype.destroy.call(this); }
};
exports.momentumshortcuts = Shortcuts;

})();
