(function(){
"use strict";
exports.name = "momentum-bg";
exports.params = [];
exports.run = function(){
	var custom = (this.wiki.getTiddlerText("$:/config/momentum/background","") || "").trim();
	if(custom){ return custom; }
	var d = new Date();
	var mm = d.getMonth() + 1, dd = d.getDate();
	var seed = "" + d.getFullYear() + (mm < 10 ? "0" : "") + mm + (dd < 10 ? "0" : "") + dd;
	var cache = this.wiki.getTiddler("$:/temp/momentum/dailyphoto");
	var source = (this.wiki.getTiddlerText("$:/config/momentum/photosource","unsplash") || "unsplash").trim();
	var key = "";
	if(source === "unsplash"){ key = (this.wiki.getTiddlerText("$:/config/momentum/unsplashkey","") || "").trim(); }
	else if(source === "pexels"){ key = (this.wiki.getTiddlerText("$:/config/momentum/pexelskey","") || "").trim(); }
	if(cache && cache.fields.date === seed){
		if(cache.fields.url){ return cache.fields.url; }
		// Unsplash was tried today and failed (rate limit, bad key, etc) - fall through to Picsum
	} else if(key){
		return ""; // fetch still in flight, avoid a Picsum flash before it resolves
	}
	var shuffle = (this.wiki.getTiddlerText("$:/config/momentum/photoseed","0") || "0").trim();
	var picsumSeed = (shuffle !== "0") ? (seed + "-" + shuffle) : seed;
	return "https://picsum.photos/seed/" + picsumSeed + "/1920/1080";
};
})();
